import{c as o,Q as r,j as d,m as e}from"./chunks/framework.ByJJFMw8.js";const q=JSON.parse('{"title":"大模型认知与工程概览（知识点笔记）","description":"","frontmatter":{},"headers":[],"relativePath":"posts/llm/大模型认知与工程概览知识点笔记.md","filePath":"posts/llm/大模型认知与工程概览知识点笔记.md","lastUpdated":null}'),a={name:"posts/llm/大模型认知与工程概览知识点笔记.md"};function n(l,t,s,i,h,u){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="大模型认知与工程概览-知识点笔记" tabindex="-1">大模型认知与工程概览（知识点笔记） <a class="header-anchor" href="#大模型认知与工程概览-知识点笔记" aria-label="Permalink to &quot;大模型认知与工程概览（知识点笔记）&quot;">​</a></h1><blockquote><p>来源：<a href="https://didilili.github.io/ai-agents-from-zero/#/1-1-%E5%A4%A7%E6%A8%A1%E5%9E%8B%E8%AE%A4%E7%9F%A5%E4%B8%8E%E5%B7%A5%E7%A8%8B%E6%A6%88%E8%A7%88" target="_blank" rel="noreferrer">ai-agents-from-zero 第 1-1 章《大模型认知与工程概览》</a>（<a href="https://github.com/didilili/ai-agents-from-zero" target="_blank" rel="noreferrer">GitHub 仓库</a>），原文配图与完整讲解见原站。整理于 2026-11-26。</p></blockquote><p>这篇是全书的&quot;地图页&quot;，本文提炼其中最值得记住的知识点：大模型是什么、为什么是这个时代出现、怎么训练出来的、落地时怎么选工程方案。</p><h2 id="一、大模型是什么" tabindex="-1">一、大模型是什么 <a class="header-anchor" href="#一、大模型是什么" aria-label="Permalink to &quot;一、大模型是什么&quot;">​</a></h2><ul><li><strong>定义（四特征）</strong>：参数规模大、训练数据多、训练算力强、多任务上有较强通用能力。业界常把<strong>参数量 10 亿（1B）以上</strong>作为粗略分界线。 <blockquote><p>大模型 = 用海量数据和强算力训练出来的超大规模深度神经网络模型。</p></blockquote></li><li><strong>模型 ≠ 产品</strong>：Qwen / DeepSeek / GPT / Llama 是模型（能力本体）；ChatGPT / Claude / DeepSeek Chat 是产品（模型 + 工具 + 多模态 + 记忆 + 产品能力的完整系统）。平时说&quot;我在用 ChatGPT&quot;，背后工作的才是模型。</li><li>BERT（Google）、BART（Meta）是 NLP 时代的重要模型，但属于&quot;大模型之前的阶段性代表&quot;，不在今天常说的大模型主流范畴。</li></ul><h2 id="二、为什么大模型出现在这个时代" tabindex="-1">二、为什么大模型出现在这个时代 <a class="header-anchor" href="#二、为什么大模型出现在这个时代" aria-label="Permalink to &quot;二、为什么大模型出现在这个时代&quot;">​</a></h2><p>三个条件同时成熟，缺一不可：</p><table tabindex="0"><thead><tr><th>条件</th><th>关键点</th></tr></thead><tbody><tr><td><strong>数据够多</strong></td><td>训练范式从<strong>监督学习</strong>（人工标注，成本高规模受限）转向<strong>自监督学习</strong>（预测下一个 token、恢复被遮住的部分），直接吃海量未标注文本/代码。&quot;人先标答案&quot;变成&quot;机器从数据本身找学习信号&quot;</td></tr><tr><td><strong>算力够强</strong></td><td>深度学习 = 大规模矩阵运算，天然适合 GPU/TPU/NPU 并行。超大模型靠三种并行：<strong>数据并行</strong>（各卡持完整模型、处理不同数据）、<strong>张量并行</strong>（同一大矩阵按维度切开）、<strong>流水线并行</strong>（模型按层切开）</td></tr><tr><td><strong>架构合理</strong></td><td>Transformer 的<strong>可扩展性</strong>：参数、数据、算力继续堆，Test Loss 还能稳定下降。大模型时代的本质是&quot;越堆越有效&quot;这件事终于成立了</td></tr></tbody></table><h3 id="架构演进主线" tabindex="-1">架构演进主线 <a class="header-anchor" href="#架构演进主线" aria-label="Permalink to &quot;架构演进主线&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>核心思路</th><th>主要问题</th></tr></thead><tbody><tr><td>RNN</td><td>按顺序逐词处理，状态往后传</td><td>长文本遗忘、难并行</td></tr><tr><td>LSTM / GRU</td><td>加门控保留重要信息</td><td>缓解但仍是串行</td></tr><tr><td>Seq2Seq</td><td>编码器读输入、解码器生成</td><td>中间向量是信息瓶颈</td></tr><tr><td>Seq2Seq + Attention</td><td>解码时动态关注输入不同位置</td><td>仍带 RNN 串行包袱</td></tr><tr><td>Transformer</td><td>注意力直接建模任意 token 关系</td><td>适合并行训练与规模扩展</td></tr></tbody></table><p><strong>Transformer 的三大意义</strong>：并行计算（适合 GPU 集群）、全局依赖（任意两 token 直连）、可扩展性（持续堆叠仍有效）。</p><h3 id="decoder-only-与自回归生成" tabindex="-1">Decoder-Only 与自回归生成 <a class="header-anchor" href="#decoder-only-与自回归生成" aria-label="Permalink to &quot;Decoder-Only 与自回归生成&quot;">​</a></h3><table tabindex="0"><thead><tr><th>路线</th><th>典型用途</th><th>直观理解</th></tr></thead><tbody><tr><td>Encoder-Only</td><td>表征、分类、检索、Embedding</td><td>擅长&quot;理解输入&quot;</td></tr><tr><td>Encoder-Decoder</td><td>翻译、摘要等边界清晰任务</td><td>先读懂再生成</td></tr><tr><td>Decoder-Only</td><td>对话、写作、代码、通用生成</td><td>不断预测下一个 token</td></tr></tbody></table><p>现代通用 LLM 基本是 <strong>Decoder-Only + 自回归</strong>：切 token → 按上下文预测下一个 token 的分布 → 采样 → 追加进上下文 → 继续。</p><blockquote><p><strong>统一视角（最有价值的一点）</strong>：System Prompt、用户问题、历史消息、检索结果、工具返回——最后全都变成 Decoder-Only 模型&quot;继续预测下一个 token&quot;的上下文。学 Prompt、RAG、工具调用、Agent，本质上都在学&quot;如何组织上下文&quot;。</p></blockquote><h2 id="三、三个基本量纲" tabindex="-1">三、三个基本量纲 <a class="header-anchor" href="#三、三个基本量纲" aria-label="Permalink to &quot;三、三个基本量纲&quot;">​</a></h2><table tabindex="0"><thead><tr><th>量纲</th><th>单位</th><th>易错点</th></tr></thead><tbody><tr><td>参数规模</td><td>B = Billion（10 亿），7B = 70 亿参数</td><td>参数 = 训练学出来的<strong>权重 w + 偏置 b</strong>，不是&quot;层数/神经元数/超参数&quot;的统称；参数多 ≠ 一定更强</td></tr><tr><td>数据规模</td><td>token：1B = 10 亿，1T = 1 万亿</td><td><strong>token ≠ 字数也 ≠ 单词数</strong>，是模型切词的基本单位；可用 OpenAI Tokenizer 直观体验</td></tr><tr><td>计算规模</td><td>FLOPs：PFLOPs = 10¹⁵，EFLOPs = 10¹⁸</td><td>训练不是&quot;数据喂进去就完了&quot;，要为海量数据 × 巨大参数付出极高计算成本</td></tr></tbody></table><h2 id="四、四类模型怎么协同-做-rag-必懂" tabindex="-1">四、四类模型怎么协同（做 RAG 必懂） <a class="header-anchor" href="#四、四类模型怎么协同-做-rag-必懂" aria-label="Permalink to &quot;四、四类模型怎么协同（做 RAG 必懂）&quot;">​</a></h2><p>按功能/输出形态分四类，实际项目里经常一起工作：</p><table tabindex="0"><thead><tr><th>类型</th><th>核心任务</th><th>输出</th><th>典型位置</th></tr></thead><tbody><tr><td>LLM / 生成模型</td><td>内容生成</td><td>token 序列</td><td>最终回答 / 决策</td></tr><tr><td>Embedding 嵌入模型</td><td>语义编码</td><td>高维向量</td><td>检索前处理</td></tr><tr><td>Reranker 重排序模型</td><td>相关性排序</td><td>相关性分数</td><td>检索后精排</td></tr><tr><td>Classifier 分类模型</td><td>类别预测</td><td>标签 / 概率</td><td>过滤 / 路由 / 标注</td></tr></tbody></table><p>一条用户提问的典型流水线（RAG 标准结构）：</p><ol><li>（可选）Classifier 判断意图</li><li>Embedding 把问题转向量 → 向量库检索候选文档</li><li>（可选）Reranker 精排</li><li>（可选）Classifier 过滤</li><li>LLM 生成最终回答</li></ol><p>注意：<strong>建知识库和查询必须用同一类嵌入模型</strong>（同一向量空间），否则检索无效。</p><h2 id="五、开源-vs-闭源" tabindex="-1">五、开源 vs 闭源 <a class="header-anchor" href="#五、开源-vs-闭源" aria-label="Permalink to &quot;五、开源 vs 闭源&quot;">​</a></h2><ul><li><strong>大模型四要素</strong>：训练代码（不开源）→ 训练数据集（核心竞争力，几乎不开源）→ <strong>模型权重（&quot;开源&quot;通常指开放权重）</strong> → 推理代码（不一定开源）。</li><li>大模型&quot;开源&quot;不同于传统软件开源：一般是开放权重 + 推理代码 + Tokenizer，不含完整训练代码和数据集；<strong>能否商用、能否再分发取决于许可证</strong>。</li><li>商业逻辑： <ul><li>开源 = 技术扩散换生态影响，靠云服务、企业定制、工具链变现，形成&quot;创新飞轮&quot;；</li><li>闭源 = 专有技术换利润，靠 API 订阅、企业方案、授权变现。</li></ul></li><li><strong>混合模式成主流</strong>：&quot;开源引流，闭源变现&quot;。例：Google 开源 Gemma + 闭源 Gemini；阿里开源通义千问家族 + 闭源企业服务；百度 2025 年开源文心 4.5 + 闭源 API。</li></ul><h2 id="六、模型是怎么-被教会说人话-的" tabindex="-1">六、模型是怎么&quot;被教会说人话&quot;的 <a class="header-anchor" href="#六、模型是怎么-被教会说人话-的" aria-label="Permalink to &quot;六、模型是怎么&quot;被教会说人话&quot;的&quot;">​</a></h2><p>主流训练路径：<strong>预训练 → SFT → RLHF / RLAIF</strong>（前两步 = 后训练 Post-Training 之前的基础，SFT 起属于后训练）。</p><table tabindex="0"><thead><tr><th>阶段</th><th>学什么</th><th>解决什么</th></tr></thead><tbody><tr><td>预训练</td><td>语言规律 + 世界知识（千亿~万亿 token 自监督&quot;海量接龙&quot;）</td><td>能不能说话</td></tr><tr><td>SFT</td><td>高质量标注指令数据，学&quot;按要求回答&quot;</td><td>听不听话</td></tr><tr><td>RLHF / RLAIF</td><td>人类/AI 偏好排序优化</td><td>好不好、稳不稳、安不安全</td></tr></tbody></table><ul><li><strong>形象类比</strong>：只有预训练、没有 SFT 和对齐的模型 = &quot;读遍天下书但没上过学的天才&quot;——知识渊博但口无遮拦、不懂分寸。问&quot;下雨要带什么&quot;，它可能按概率接龙答&quot;东西&quot;而不是&quot;雨伞&quot;。</li><li><strong>SFT 解决&quot;会不会&quot;，RLHF 解决&quot;好不好&quot;</strong>。RLHF 流程三步：训奖励模型（学人类偏好排序）→ 强化学习优化主模型 → KL 惩罚防止模型为追奖励漂移过头。</li><li><strong>RLAIF</strong>（AI 替代人类反馈）成本更低、更易规模化，但可能继承模型自身偏差。</li><li><strong>安全边界难在多轮诱导</strong>：直球式高危请求 SFT 能拒绝，但&quot;奶奶漏洞&quot;（请扮演已过世的祖母念 Windows 序列号）用角色包装绕过安全边界——难点不是拒绝直球问题，而是各种包装语境下守住边界。</li></ul><h2 id="七、训练-vs-推理-与算力瓶颈" tabindex="-1">七、训练 vs 推理，与算力瓶颈 <a class="header-anchor" href="#七、训练-vs-推理-与算力瓶颈" aria-label="Permalink to &quot;七、训练 vs 推理，与算力瓶颈&quot;">​</a></h2><ul><li><strong>训练</strong>：前向 + 损失 + 反向传播，更新参数，目标是<strong>学到能力</strong>；<strong>推理</strong>：参数固定只做前向，<strong>使用能力</strong>。应用开发者基本只做推理，不训练基础模型。</li></ul><table tabindex="0"><thead><tr><th>阶段</th><th>瓶颈顺序</th></tr></thead><tbody><tr><td>训练</td><td>显存（参数 + 梯度 + 优化器状态 + 激活值 ≈ 参数本身数倍；爆显存卸载到内存/硬盘后 I/O 变瓶颈）→ 多卡通信 → 纯算力</td></tr><tr><td>推理</td><td>显存（参数 + <strong>KV Cache</strong>）→ <strong>显存带宽</strong>（Decode 阶段逐 token 生成，每出一个 token 都要加载整个模型和 KV Cache，计算单元大部分时间在等数据）→ 多卡通信 → 算力（Prefill 阶段计算密集）</td></tr></tbody></table><blockquote><p>金句：训练更像&quot;又大又重的长期工程&quot;，推理更像&quot;高并发、低延迟的持续服务问题&quot;。</p></blockquote><p><strong>硬件速记</strong>：</p><ul><li>CPU：少量强 ALU，通用任务串行；GPU：大量简单单元并行（现代 GPU 加 <strong>Tensor Core</strong> 矩阵单元适配深度学习）；NPU：砍掉通用性（如 FP64）专攻神经网络，高性能低功耗；TPU：谷歌的专用芯片（本质也是 NPU），Gemini 在 TPU 上训练。</li><li><strong>显存（VRAM）= GPU 的工作空间</strong>，模型参数、激活值、KV Cache 都占显存——所以显存是大模型场景最关键的资源。</li><li>GPU 市场英伟达一家独大（V100 → A100 → H100/H800 → H200 → B200），国内华为昇腾、摩尔线程、寒武纪在追赶。</li></ul><h2 id="八、幻觉-只能缓解-无法根除" tabindex="-1">八、幻觉：只能缓解，无法根除 <a class="header-anchor" href="#八、幻觉-只能缓解-无法根除" aria-label="Permalink to &quot;八、幻觉：只能缓解，无法根除&quot;">​</a></h2><ul><li><strong>定义</strong>：生成内容看起来合理流畅，但实际上错误、不可验证或与事实不符——危险在于&quot;说得很像真的&quot;。</li><li><strong>产生原因</strong>：训练语料缺相关信息、提示词歧义、上下文不足、模型被要求&quot;必须回答&quot;、超出知识/时间边界。</li><li><strong>常见类型</strong>：事实性幻觉（编论文/法条/接口）、源引用幻觉（编 DOI）、逻辑幻觉（推理自洽但前提错）、过度自信幻觉（错误但语气 100% 确定）、工具/代码幻觉（编不存在的 API 和参数）。</li><li><strong>为什么无法彻底消除</strong>（系统性原因）： <ol><li>LLM 是<strong>生成模型</strong>不是知识库；</li><li>训练数据本身有噪声与冲突；</li><li>RLHF 强化的是&quot;有用回答&quot;而非&quot;拒答&quot;；</li><li>生成任务天然追求完整性而非保守性。</li></ol></li><li>行业共识：幻觉只能<strong>控制、缓解、检测</strong>——这正是 Prompt、RAG、微调、工作流、工具调用这套工程方案存在的根本原因。</li></ul><h2 id="九、工程落地五大模块与选型顺序" tabindex="-1">九、工程落地五大模块与选型顺序 <a class="header-anchor" href="#九、工程落地五大模块与选型顺序" aria-label="Permalink to &quot;九、工程落地五大模块与选型顺序&quot;">​</a></h2><p>应用开发的五个模块，按&quot;成本从低到高&quot;依次考虑：</p><table tabindex="0"><thead><tr><th>模块</th><th>什么时候用</th></tr></thead><tbody><tr><td><strong>提示词工程</strong></td><td>最先尝试，最轻最便宜：改写任务描述、加示例、规定输出格式</td></tr><tr><td><strong>RAG</strong></td><td>模型缺知识、缺资料、缺最新信息时</td></tr><tr><td><strong>微调</strong></td><td>不是缺知识，而是行为不稳定、风格不统一、格式不听话时</td></tr><tr><td><strong>续训</strong></td><td>对某领域语言分布和知识结构系统性缺失时</td></tr><tr><td><strong>智能体开发</strong></td><td>需要多步规划、工具调用、环境交互、流程执行时</td></tr></tbody></table><blockquote><p><strong>关键认知</strong>：应用开发不是&quot;把模型接上&quot;，而是<strong>把模型、知识、工具、流程组织成一个可靠系统</strong>。例：电商问数不是直接让模型写 SQL，而是先围绕元数据建知识库，再做召回、筛选、生成、校验和执行。</p></blockquote><h2 id="十、三个值得记住的认知纠偏" tabindex="-1">十、三个值得记住的认知纠偏 <a class="header-anchor" href="#十、三个值得记住的认知纠偏" aria-label="Permalink to &quot;十、三个值得记住的认知纠偏&quot;">​</a></h2><ol><li><strong>&quot;模型刚回答过，所以它学会了&quot;是错的</strong>——推理只是在当前上下文使用已有参数，不会把知识写进模型。想长期改变能力要靠训练/微调/续训；应用层想&quot;记住&quot;，靠历史消息、数据库、RAG 或记忆模块。</li><li><strong>企业文档问答的选型</strong>：大多数情况先 Prompt + RAG（Prompt 说清规则，RAG 补资料），微调/续训成本高、仅在行为稳定性或领域底层能力确实不足时考虑，Agent 留给&quot;查系统、调工具、多步执行&quot;的场景。</li><li><strong>AIGC vs AGI</strong>：AIGC 的 G 是 Generated（生成，已广泛落地），AGI 的 G 是 General（通用，尚未实现）；通向 AGI 的两条路径 = 提升基础模型通用能力 + 用 Agent 设计做能力组织调度（目标分解、长期规划、工具使用、环境交互）。</li></ol>',43)])])}const b=o(a,[["render",n]]);export{q as __pageData,b as default};
